211. function Get-DebugSymbols([string]$buildId, [string]$cacheDir, [string]$serverUrl) {
212.     $debugFile = Join-Path $cacheDir "$buildId.debug"
213. 
214.     if (Test-Path $debugFile) {
215.         Write-Verbose "Using cached symbols for BuildId $buildId"
216.         return $debugFile
217.     }
218. 
219.     $url = "$serverUrl/_.debug/elf-buildid-sym-$buildId/_.debug"
220.     Write-Verbose "Downloading symbols from $url"
221. 
222.     $savedProgressPreference = $ProgressPreference
223.     try {
224.         $ProgressPreference = 'SilentlyContinue'
225.         Invoke-WebRequest -Uri $url -OutFile $debugFile -UseBasicParsing -TimeoutSec 120
226. 
227.         # Verify the download is an ELF file (starts with 0x7f ELF)
228.         $stream = [System.IO.File]::OpenRead($debugFile)
229.         try {
230.             $header = [byte[]]::new(4)
231.             $bytesRead = $stream.Read($header, 0, 4)
232.         }
233.         finally {
