257. # Try to identify the .NET runtime version and commit hash by matching a BuildId against
258. # locally-installed runtime packs (SDK workloads) and the NuGet package cache.
259. function Find-RuntimeVersion([string]$buildId, [string]$libraryName, [string]$llvmReadelf) {
260.     # Map library name to candidate runtime pack names
261.     $packNames = @()
262.     if ($libraryName -like '*monosgen*') {
263.         $packNames += 'Microsoft.NETCore.App.Runtime.Mono.android-{0}'
264.     }
265.     elseif ($libraryName -like '*coreclr*') {
266.         $packNames += 'Microsoft.NETCore.App.Runtime.android-{0}'
267.     }
268.     else {
269.         # libSystem.*.so can be in either pack
270.         $packNames += 'Microsoft.NETCore.App.Runtime.Mono.android-{0}'
271.         $packNames += 'Microsoft.NETCore.App.Runtime.android-{0}'
272.     }
273. 
274.     $rids = @('arm64', 'arm', 'x64', 'x86')
275.     $expandedPackNames = foreach ($tmpl in $packNames) { foreach ($rid in $rids) { $tmpl -f $rid } }
276. 
277.     # Build list of directories to search
278.     $searchRoots = @()
279. 
280.     # 1. SDK packs folder (workload installs — most likely for MAUI apps)
281.     $dotnetRoot = if ($env:DOTNET_ROOT) { $env:DOTNET_ROOT }
282.                   elseif (Test-Path (Join-Path $HOME '.dotnet')) { Join-Path $HOME '.dotnet' }
283.                   else { $null }
284.     if ($dotnetRoot) {
285.         foreach ($pn in $expandedPackNames) {
286.             $p = Join-Path $dotnetRoot "packs/$pn"
287.             if (Test-Path $p) { $searchRoots += $p }
288.         }
289.     }
290. 
291.     # 2. NuGet packages cache
292.     $nugetDir = if ($env:NUGET_PACKAGES) { $env:NUGET_PACKAGES }
293.                 else { Join-Path $HOME '.nuget/packages' }
294.     foreach ($pn in $expandedPackNames) {
295.         $p = Join-Path $nugetDir $pn.ToLowerInvariant()
296.         if (Test-Path $p) { $searchRoots += $p }
297.     }
298. 
299.     foreach ($root in $searchRoots) {
300.         foreach ($versionDir in (Get-ChildItem $root -Directory -ErrorAction SilentlyContinue)) {
301.             # Find the native library under this version directory
302.             $soFile = Get-ChildItem $versionDir.FullName -Recurse -Filter $libraryName -ErrorAction SilentlyContinue | Select-Object -First 1
303.             if (-not $soFile) { continue }
304. 
305.             # Read BuildId from the local binary
306.             $localBuildId = $null
307.             if ($llvmReadelf) {
308.                 $readelfOut = (& $llvmReadelf --notes $soFile.FullName 2>$null) -join "`n"
309.                 if ($readelfOut -match 'Build ID:\s*([0-9a-fA-F]+)') {
310.                     $localBuildId = $Matches[1].ToLowerInvariant()
311.                 }
312.             }
313.             if (-not $localBuildId) { continue }
314.             if ($localBuildId -ne $buildId) { continue }
315. 
316.             # Match found — extract commit hash from .nuspec
317.             $version = $versionDir.Name
318.             $commit = $null
319.             $nuspec = Get-ChildItem $versionDir.FullName -Filter '*.nuspec' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
320.             if ($nuspec) {
321.                 try {
322.                     $xml = [xml](Get-Content $nuspec.FullName -Raw)
323.                     $repoNode = $xml.package.metadata.repository
324.                     if ($repoNode -and $repoNode.commit) {
325.                         $commit = $repoNode.commit
326.                     }
327.                 }
328.                 catch {
329.                     Write-Verbose "Could not parse nuspec for version $version`: $_"
330.                 }
331.             }
332. 
333.             return [PSCustomObject]@{
334.                 Version  = $version
335.                 Commit   = $commit
336.                 PackPath = $versionDir.FullName
337.             }
338.         }
339.     }
340. 
341.     return $null
342. }
