                best = die
                best_span = span
    return die_name(best) if best else None

def line_for_cu(cu, addr):
    lp = cu.dwarfinfo.line_program_for_CU(cu)
    if not lp: return None
    prev = None
    for entry in lp.get_entries():
        st = entry.state
        if st is None: continue
        if st.end_sequence:
            if prev and prev.address <= addr:
                return prev
            prev = None
            continue
        if st.address > addr:
            return prev
        prev = st
    return prev

def file_for_state(lp, state):
    if not state or state.file == 0: return None
    header = lp.header
    fe = header['file_entry'][state.file - 1]
    name = fe.name.decode('utf-8','replace') if isinstance(fe.name, bytes) else str(fe.name)
    dirs = header['include_directory']
    dir_index = fe.dir_index
    directory = ''
    if dir_index:
        de = dirs[dir_index - 1]
        directory = de.decode('utf-8','replace') if isinstance(de, bytes) else str(de)
    if directory:
        return directory.rstrip('/\\') + '/' + name
    return name

